"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[72729],{72729:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-redemption-of-time.png\\"\\n          title=\\"삼체X: 관상지주\\"\\n          author=\\"바오수\\"\\n          publisher=\\"서삼독\\"\\n          publishedDate=\\"2025-12-24\\"\\n          isbn=\\"9791193904619\\"\\n          rating=3.5\\n          tags=\\"sf\\"\\n        />\\n</center>\\n\\n## Review\\n기존 ```삼체``` 시리즈의 열렬한 팬이었던 바오수가 쓴 동인지가 원작자 류츠신의 인정을 받아 공식 외전으로 출간된 작품이다.  \\n시리즈에서 가장 흥미로우면서도 베일에 싸여 있던 인물인 ```윈톈밍```의 뇌가 삼체 함대에 노획된 이후의 이야기를 다룬다.  \\n<br>\\n원작에서 독자들의 궁금증을 자아냈던 수많은 떡밥들을 회수한다.  \\n삼체인의 실제 모습은 어떠한지, 윈톈밍이 어떻게 살아남아 동화 세 가지를 전달할 수 있었는지 등 가려웠던 부분을 시원하게 긁어준다.  \\n<br>\\n하지만 너무 많은 것을 설명하려다 보니 원작 특유의 <mark>미지의 공포</mark>와 여백의 미가 사라진 느낌이다.  \\n때로는 상상의 영역으로 남겨두는 편이 더 좋았을 것이라는 생각도 든다.  \\n<br>\\n특히 우주의 기원과 신적 존재인 관상지주와 잠복자의 대립까지 스케일이 확장되는데, 개인적으로는 이 부분이 다소 뇌절처럼 느껴졌다.  \\n원작의 하드 SF 느낌보다는 스페이스 오페라 쪽에 더 가까워진 듯하다.  \\n<br>\\n그래도 삼체 세계관을 사랑하는 팬이라면 한 번쯤 읽어볼 만한 흥미로운 작품이다.  \\n아쉬운 점은 많지만 윈톈밍의 서사를 완성했다는 점에서는 의의가 있다."}')}}]);